import { readFileSync } from "fs";
import type { ConnectionOptions } from "tls";

/**
 * TLS options for the `pg` driver (the Pool in database.ts and scripts/migrate.ts),
 * with libpq's sslmode semantics, so that they match what Prisma, Keycloak and psql
 * do with the same env file.
 *
 * The compose files fill these variables, with paths inside the container:
 *   DB_SSLMODE         disable | prefer | require | verify-ca | verify-full
 *   DB_SSL_CA_FILE     CA that signed the server certificate (PEM)
 *   DB_SSL_PFX_FILE    client certificate and key in PKCS#12, generated by `make db-certs`
 *
 * Prisma reads its own parameters from the URL instead: `sslcert` there means the
 * CA, while for `pg` it is the client certificate. That is why `pg` must not see
 * the SSL parameters of APP_DATABASE_URL, see stripSslParams.
 */
export function pgSslConfig(): false | ConnectionOptions {
  const mode = process.env.DB_SSLMODE || "disable";
  if (mode === "disable") return false;

  const caFile = process.env.DB_SSL_CA_FILE;
  const pfxFile = process.env.DB_SSL_PFX_FILE;

  const ssl: ConnectionOptions = {
    // As in libpq: with a CA, `require` verifies the chain as `verify-ca` does.
    rejectUnauthorized: mode.startsWith("verify") || Boolean(caFile),
  };
  if (caFile) ssl.ca = readFileSync(caFile);
  if (pfxFile) {
    ssl.pfx = readFileSync(pfxFile);
    ssl.passphrase = "";
  }
  // Only verify-full checks that the certificate belongs to DB_HOST.
  if (mode !== "verify-full") ssl.checkServerIdentity = () => undefined;
  return ssl;
}

const SSL_PARAMS = [
  "sslmode",
  "sslcert",
  "sslkey",
  "sslrootcert",
  "sslidentity",
  "sslpassword",
  "sslaccept",
  "uselibpqcompat",
];

/**
 * A connection string without its SSL parameters. `pg` lets the ones in the URL
 * win over the `ssl` option, and would read Prisma's `sslcert` (the CA) as its
 * client certificate.
 */
export function stripSslParams(connectionString: string): string {
  const url = new URL(connectionString);
  for (const param of SSL_PARAMS) url.searchParams.delete(param);
  return url.toString();
}
